CREATE TABLE self_service_profiles (tenant_id VARCHAR(64) NOT NULL, id VARBINARY(64) NOT NULL, name VARCHAR(255) NOT NULL, doc LONGTEXT NOT NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, PRIMARY KEY (tenant_id,id), UNIQUE KEY self_service_profiles_name (tenant_id,name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE self_service_custom_texts (tenant_id VARCHAR(64) NOT NULL, profile_id VARBINARY(64) NOT NULL, language VARCHAR(16) NOT NULL, page VARCHAR(64) NOT NULL, doc LONGTEXT NOT NULL, PRIMARY KEY (tenant_id,profile_id,language,page)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE sso_tickets (tenant_id VARCHAR(64) NOT NULL, id VARBINARY(64) NOT NULL, profile_id VARBINARY(64) NOT NULL, token_hash VARCHAR(64) NOT NULL, connection_id VARBINARY(255) NOT NULL, doc LONGTEXT NOT NULL, created_at BIGINT NOT NULL, expires_at BIGINT NOT NULL, revoked_at BIGINT NULL, used_at BIGINT NULL, PRIMARY KEY (tenant_id,id), UNIQUE KEY sso_tickets_hash (tenant_id,token_hash)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE INDEX sso_tickets_profile ON sso_tickets (tenant_id,profile_id);
CREATE TABLE connection_profiles (tenant_id VARCHAR(64) NOT NULL, id VARBINARY(64) NOT NULL, name VARCHAR(255) NOT NULL, doc LONGTEXT NOT NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, PRIMARY KEY (tenant_id,id), UNIQUE KEY connection_profiles_name (tenant_id,name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
